-- RootishArrayStack：跨块按位插入与删除。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT 'RootishArrayStack 的按位插入与删除', '插入从尾部向 i 右移后写入，删除从 i 向尾部左移；搬移通过全局下标 get/set 跨块进行。', course.id, parent.id, 'ods-rootisharraystack-update', 'AISTU', 1, 'REVIEWED', 31, 0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='ods-rootisharraystack-update' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id,'ods-rootisharraystack-update',1,'REVIEWED','RootishArrayStack 的按位插入与删除',JSON_OBJECT('summary','add(i,x) 必要时先 grow，随后从尾部向 i 执行 set(j,get(j-1)) 并写入 x；remove(i) 从 i 起执行 set(j,get(j+1))，再 shrink。忽略块增删时成本分别为 O(1+n-i) 与 O(n-i)。','steps',JSON_ARRAY('插入时先保证总容量足够，再从后向前搬移','删除时保存原值，再从前向后搬移后继元素','所有搬移使用逻辑下标，因此可跨越块边界','更新结束后再按需 grow 或 shrink'),'prerequisite',JSON_OBJECT('contentKey','ods-rootisharraystack-index-mapping','title','RootishArrayStack 的下标到块映射','description','先掌握全局下标如何落到具体块。'),'nextStep',JSON_OBJECT('contentKey','ods-rootisharraystack-grow-shrink','title','RootishArrayStack 的块增长与收缩','description','继续学习何时追加或删除末尾块。')),JSON_OBJECT('id','rootisharraystack-update-v1','prompt','RootishArrayStack 在位置 i 插入时，为避免覆盖原元素，应从哪个方向搬移？','options',JSON_ARRAY(JSON_OBJECT('id','RIGHT_TO_LEFT','text','从尾部向 i 逐位右移'),JSON_OBJECT('id','LEFT_TO_RIGHT','text','从 i 向尾部逐位右移')),'correctOptionId','RIGHT_TO_LEFT','correctExplanation','正确：从后向前复制，才能在写入前保留每个前驱元素。','incorrectExplanation','不正确：从前向后右移会先覆盖仍需读取的元素。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='ods-rootisharraystack-update' AND existing.content_version=1 WHERE point.content_key='ods-rootisharraystack-update' AND existing.id IS NULL;
